CREATE TABLE IF NOT EXISTS previsions_ventes (    id SERIAL PRIMARY KEY,    mois DATE,    prevision NUMERIC);CREATE TABLE IF NOT EXISTS previsions_production (    id SERIAL PRIMARY KEY,    mois DATE,    prevision NUMERIC);CREATE TABLE IF NOT EXISTS comparatif_reel_prevu (    id SERIAL PRIMARY KEY,    mois DATE,    prevision NUMERIC,    mae NUMERIC,    reel NUMERIC,    ecart NUMERIC,    ecart_pourcentage NUMERIC);